"""Regenerate exact resolvent coefficient tables from SymPy 1.14."""
import json
from pathlib import Path
import sympy as sp
from sympy.polys.numberfields.resolvent_lookup import resolvent_coeff_lambdas

assert sp.__version__ == '1.14.0'
root = Path(__file__).resolve().parents[1] / 'src'
header = ('// SPDX-License-Identifier: MIT\n'
          '// SPDX-FileCopyrightText: Copyright 2026 OpenQL Project\n'
          '// Generated by scripts/generate-galois.py from SymPy 1.14 (BSD-3-Clause).\n'
          '// Do not edit by hand.\nexport default ')
resolvents = {}
for (degree, number), coefficients in resolvent_coeff_lambdas.items():
    symbols = sp.symbols(f'c0:{degree}')
    resolvents[f'{degree},{number}'] = [
        [{'powers': list(monom), 'coefficient': str(coeff)} for monom, coeff in sp.Poly(fn(*symbols), *symbols).terms()]
        for fn in coefficients
    ]
(root / 'polys/numberfields/resolventlookupdata.ts').write_text(header + json.dumps(resolvents, separators=(',', ':')) + ';\n')
